import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';

// Execute the actual production monetization module with a deterministic
// Capacitor bridge and DOM. No real ad traffic is generated by unit tests.
test('banner awaits SDK callback, backs off after no-fill and resumes safely',async t=>{
 t.mock.timers.enable({apis:['setTimeout','Date'],now:10000});
 const callbacks=new Map(),classes=new Set(),storage=new Map();
 let requests=0,hides=0,resumes=0,modal=false,removes=0;
 const emit=(event,detail)=>{for(const fn of callbacks.get(event)||[])fn(detail)};
 const nav={getClientRects:()=>[1],getBoundingClientRect:()=>({top:756,bottom:852})};
 const header={getBoundingClientRect:()=>({bottom:70})};
 const overlay={hidden:false,closest:()=>null,getClientRects:()=>[1]};
 const plugin={
  async requestConsentInfo(){return {canRequestAds:true,status:'NOT_REQUIRED',isConsentFormAvailable:false}},
  async initialize(){},
  async addListener(event,fn){if(!callbacks.has(event))callbacks.set(event,[]);callbacks.get(event).push(fn)},
  async showBanner(options){assert.equal(options.isTesting,true);assert.equal(options.adSize,'BANNER');requests++},
  async prepareInterstitial(){},
  async hideBanner(){hides++},
  async resumeBanner(){resumes++},
  async removeBanner(){removes++}
 };
 globalThis.__rivoNativeMock=plugin;
 globalThis.document={
  visibilityState:'visible',documentElement:{clientWidth:393,style:{setProperty(){}}},
  body:{classList:{contains:c=>classes.has(c),toggle(c,on){if(on)classes.add(c);else classes.delete(c)}}},
  querySelector(sel){return sel.includes('mobilebar')?nav:sel.includes('.topbar')?header:null},
  querySelectorAll(){return modal?[overlay]:[]},addEventListener(){}
 };
 globalThis.window={innerHeight:852,addEventListener(){},dispatchEvent(){},visualViewport:{addEventListener(){}}};
 globalThis.getComputedStyle=()=>({display:'block',visibility:'visible'});
 globalThis.MutationObserver=class{observe(){}};
 globalThis.requestAnimationFrame=fn=>fn();
 globalThis.localStorage={getItem:k=>storage.get(k)||null,setItem:(k,v)=>storage.set(k,v)};
 const source=readFileSync(new URL('../src/monetization.js',import.meta.url),'utf8')
  .replace(/import \{ Capacitor \} from '@capacitor\/core';/,"const Capacitor={isNativePlatform:()=>true,getPlatform:()=> 'android'};")
  .replace(/import \{ AdMob, AdmobConsentStatus, InterstitialAdPluginEvents, BannerAdPluginEvents, BannerAdSize, BannerAdPosition \} from '@capacitor-community\/admob';/,"const AdMob=globalThis.__rivoNativeMock;const AdmobConsentStatus={REQUIRED:'REQUIRED'};const BannerAdPluginEvents={Loaded:'loaded',FailedToLoad:'failed',SizeChanged:'size',AdImpression:'impression'};const InterstitialAdPluginEvents={AdImpression:'interImpression',FailedToLoad:'interFailed'};const BannerAdSize={BANNER:'BANNER'};const BannerAdPosition={BOTTOM_CENTER:'BOTTOM_CENTER'};")
  .replace("'./rivo-native-ad-geometry.js'",JSON.stringify(new URL('../src/rivo-native-ad-geometry.js',import.meta.url).href))
  .replace("'./banner-diagnostics.js'",JSON.stringify(new URL('../src/banner-diagnostics.js',import.meta.url).href));
 assert.ok(!source.includes("from '@capacitor"));
 const m=await import('data:text/javascript;base64,'+Buffer.from(source).toString('base64'));
 const flush=async()=>{for(let i=0;i<35;i++)await Promise.resolve()};
 const render=async()=>{m.refreshBannerPosition();t.mock.timers.tick(166);await flush()};
 assert.equal(await m.initializeAds(),true);await flush();
 assert.equal(requests,1);assert.equal(m.getBannerDiagnostics().status,'REQUESTING');
 for(let i=0;i<8;i++)await render();
 assert.equal(requests,1,'render cannot start an additional in-flight request');
 emit('failed',{code:3,message:'No fill'});await flush();
 assert.equal(m.getBannerDiagnostics().status,'NO_FILL');
 for(let i=0;i<10;i++)await render();
 assert.equal(requests,1,'render cannot bypass retry backoff');
 t.mock.timers.tick(55000);await flush();
 assert.equal(requests,1,'first retry cannot be earlier than one minute');
 t.mock.timers.tick(6000);await flush();
 t.mock.timers.tick(200);await flush();
 assert.equal(requests,2,'exactly one scheduled retry');
 emit('size',{width:320,height:50});emit('loaded');emit('impression');await flush();
 assert.equal(m.getBannerDiagnostics().status,'DISPLAYED');
 assert.equal(m.getBannerDiagnostics().impressions,1);
 assert.equal(classes.has('rivo-has-ad-banner'),true);
 modal=true;await render();assert.equal(hides,1);assert.equal(classes.has('rivo-has-ad-banner'),false);
 modal=false;await render();assert.equal(resumes,1);assert.equal(classes.has('rivo-has-ad-banner'),true);
 assert.equal(requests,2,'resume must reuse existing native banner');
 assert.equal(removes,0);
});
